:root {
  --ink: #2c2928;
  --muted: #736e6a;
  --paper: #fffdf9;
  --cream: #f8f1e8;
  --line: #e8ddd1;
  --orange: #e96540;
  --orange-dark: #c94f2e;
  --sage: #517b6c;
  --shadow: 0 16px 45px rgba(67,44,27,.1);
  --radius: 20px;
  --max-width: 1200px;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; min-height: 100vh; font-family: "DM Sans", sans-serif; color: var(--ink); background: linear-gradient(145deg, #fffdf9 0%, #fdf7ee 48%, #f6f1e9 100%); overflow-x: hidden; }
a { color: inherit; text-decoration: none; }
button, input, select, textarea { font: inherit; }
img { max-width: 100%; display: block; }

.sr-only { position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0; }
.live-background { position: fixed; inset: 0; z-index: 0; overflow: hidden; pointer-events: none; }
.background-orb { position: absolute; border-radius: 50%; filter: blur(2px); opacity: .3; }
.orb-one { width: 400px; height: 400px; background: #ffd9bd; right: -210px; top: 120px; animation: orb-drift 18s ease-in-out infinite; }
.orb-two { width: 270px; height: 270px; background: #cae1d2; left: -180px; top: 680px; animation: orb-drift 22s ease-in-out -5s infinite reverse; }
.orb-three { width: 190px; height: 190px; background: #e5cef5; right: 19%; bottom: -105px; animation: orb-drift 16s ease-in-out -8s infinite; }
.floating-seed { position: absolute; width: 10px; height: 10px; border-radius: 50% 50% 50% 0; background: rgba(233,101,64,.28); transform: rotate(45deg); }
.seed-one { left: 12%; top: 18%; animation: seed-float 12s ease-in-out infinite; }
.seed-two { right: 8%; top: 48%; width: 13px; height: 13px; background: rgba(81,123,108,.25); animation: seed-float 16s ease-in-out -4s infinite; }
.seed-three { left: 29%; bottom: 13%; width: 7px; height: 7px; background: rgba(212,151,46,.28); animation: seed-float 11s ease-in-out -7s infinite; }
.seed-four { right: 35%; top: 12%; width: 6px; height: 6px; background: rgba(131,96,177,.2); animation: seed-float 14s ease-in-out -2s infinite; }
@keyframes orb-drift { 0%, 100% { transform: translate3d(0,0,0) scale(1); } 50% { transform: translate3d(-28px,24px,0) scale(1.12); } }
@keyframes seed-float { 0%, 100% { transform: translate3d(0,0,0) rotate(45deg); } 50% { transform: translate3d(18px,-28px,0) rotate(160deg); } }
.topbar, #app, .site-footer { position: relative; z-index: 1; }
.topbar { max-width: var(--max-width); margin: 0 auto 12px; padding: 0 28px; display: flex; align-items: center; justify-content: space-between; gap: 24px; height: 82px; background: rgba(255,255,255,.7); backdrop-filter: blur(12px); border: 1px solid rgba(232,221,209,.9); border-radius: 0 0 24px 24px; box-shadow: 0 12px 26px rgba(67,44,27,.04); position: sticky; top: 0; }
.brand { display: flex; align-items: center; gap: 9px; color: var(--ink); font-family: "Playfair Display", serif; font-size: 24px; font-weight: 700; letter-spacing: -1px; }
.brand-mark { display: inline-grid; place-items: center; width: 31px; height: 31px; border-radius: 10px; background: var(--orange); color: white; font-family: "DM Sans", sans-serif; font-size: 16px; transform: rotate(-8deg); box-shadow: 0 5px 13px rgba(233,101,64,.25); }
.topnav { display: flex; align-items: center; gap: 26px; margin-left: auto; }
.topnav a { color: var(--muted); font-size: 14px; font-weight: 700; position: relative; }
.topnav a::after { content: ""; position: absolute; left: 0; right: 0; bottom: -7px; height: 2px; border-radius: 999px; background: var(--orange); transform: scaleX(0); transform-origin: left; transition: transform .2s ease; }
.topnav a:hover::after, .topnav a:focus-visible::after { transform: scaleX(1); }
#account-actions { display: flex; gap: 12px; align-items: center; }
.button { border: 1px solid transparent; border-radius: 12px; padding: 12px 18px; background: var(--orange); color: white; font: 700 14px "DM Sans", sans-serif; cursor: pointer; display: inline-flex; align-items: center; justify-content: center; gap: 7px; box-shadow: 0 12px 26px rgba(233,101,64,.12); transition: transform .2s ease, box-shadow .2s ease; }
.button:hover { transform: translateY(-1px); box-shadow: 0 14px 28px rgba(233,101,64,.18); }
.button.secondary { background: rgba(255,255,255,.82); border-color: rgba(232,221,209,.95); color: var(--ink); box-shadow: none; }
#app { max-width: var(--max-width); margin: 0 auto; padding: 10px 28px 48px; }
.section-shell { margin: 0 auto 18px; }
.hero { display: grid; grid-template-columns: 1.05fr .95fr; gap: 45px; align-items: center; min-height: 500px; padding: 56px 24px 68px; }
.eyebrow { display: inline-block; padding: 8px 12px; border-radius: 999px; background: rgba(81,123,108,.09); border: 1px solid rgba(81,123,108,.12); color: var(--sage); font-size: 11px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; }
.hero-copy h1, .section-title, .ui-panel h3, .dense-section h3 { font-family: "Playfair Display", serif; letter-spacing: -1.4px; }
.hero-copy h1 { font-size: clamp(44px, 5.6vw, 68px); line-height: 1.03; margin: 14px 0 20px; max-width: 610px; }
.hero-copy h1 em { color: var(--orange); font-style: normal; }
.hero-copy p { font-size: 17px; line-height: 1.7; color: var(--muted); max-width: 520px; margin: 0 0 28px; }
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }
.hero-art { position: relative; min-height: 390px; }
.art-photo { position: absolute; right: 9%; top: 10px; width: 76%; height: 350px; object-fit: cover; border: 8px solid rgba(255,255,255,.8); border-radius: 42% 42% 30% 30%; box-shadow: var(--shadow); transform: rotate(3deg); }
.art-card { position: absolute; bottom: 5px; left: 0; min-width: 200px; background: rgba(255,253,249,.9); backdrop-filter: blur(12px); border: 1px solid rgba(232,221,209,.82); border-radius: 18px; padding: 16px 18px; box-shadow: 0 18px 35px rgba(67,44,27,.08); }
.art-card strong { display: block; font-family: "Playfair Display", serif; font-size: 21px; }
.art-card span { display: block; color: var(--muted); font-size: 12px; margin-top: 4px; }
.art-chip { position: absolute; right: 0; top: 60px; padding: 9px 13px; border-radius: 50px; background: rgba(229,239,232,.88); font-weight: 700; font-size: 12px; }
.value-strip { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; margin-bottom: 72px; }
.value-card { display: flex; align-items: flex-start; gap: 12px; padding: 18px 18px 16px; border-radius: 18px; background: rgba(255,255,255,.72); border: 1px solid rgba(232,221,209,.82); box-shadow: 0 10px 20px rgba(67,44,27,.04); }
.value-icon { width: 35px; height: 35px; display: grid; place-items: center; border-radius: 11px; background: linear-gradient(135deg,#fff5ee,#ffe9d4); color: var(--orange); font-size: 17px; border: 1px solid rgba(233,101,64,.12); }
.value-card strong { display: block; font-size: 14px; }
.value-card span { display: block; margin-top: 4px; font-size: 12px; color: var(--muted); line-height: 1.5; }
.section-head { display: flex; justify-content: space-between; gap: 15px; align-items: end; margin-bottom: 22px; }
.section-title { font-size: 38px; margin: 8px 0 0; line-height: 1.08; }
.search-panel { display: grid; grid-template-columns: 1.5fr 1fr 1fr 1fr auto; gap: 12px; padding: 16px; border-radius: 24px; background: rgba(255,250,245,.9); border: 1px solid rgba(232,221,209,.8); box-shadow: 0 12px 28px rgba(67,44,27,.04); margin-bottom: 18px; }
.field { display: block; }
.field input, .field select { width: 100%; border: 1px solid var(--line); border-radius: 10px; padding: 11px 12px; background: #fff; color: var(--ink); outline: none; }
.field input:focus, .field select:focus { border-color: var(--orange); box-shadow: 0 0 0 3px rgba(233,101,64,.12); }
.recipe-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; }
.recipe-card { background: rgba(255,255,255,.9); border: 1px solid rgba(232,221,209,.9); border-radius: 22px; overflow: hidden; box-shadow: 0 14px 26px rgba(41,31,24,.05); transition: transform .2s ease, box-shadow .2s ease; }
.recipe-card:hover { transform: translateY(-5px); box-shadow: 0 22px 30px rgba(41,31,24,.08); }
.recipe-image { height: 180px; background: linear-gradient(135deg,#f3d3b3,#d79f79); position: relative; overflow: hidden; }
.save-card { position: absolute; right: 12px; top: 12px; }
.icon-button { width: 34px; height: 34px; border: 0; border-radius: 50%; background: rgba(255,255,255,.94); display: grid; place-items: center; cursor: pointer; box-shadow: 0 3px 12px rgba(0,0,0,.08); }
.recipe-card-body { padding: 16px; }
.card-context { display: flex; gap: 6px; align-items: center; flex-wrap: wrap; }
.tag, .origin-tag, .flavour-tag { display: inline-block; padding: 6px 9px; border-radius: 999px; font-size: 10px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
.tag { color: var(--sage); background: linear-gradient(135deg,#eef6ee,#edf5f0); }
.origin-tag { color: #9d5b2d; background: linear-gradient(135deg,#fff1e8,#ffe9d7); }
.flavour-tag { color: #7d589f; background: linear-gradient(135deg,#f4ebff,#efe6ff); }
.recipe-card h3 { font-family: "Playfair Display", serif; font-size: 23px; line-height: 1.15; letter-spacing: -.5px; margin: 10px 0 6px; }
.recipe-card p { margin: 0; font-size: 12px; color: var(--muted); line-height: 1.6; }
.meta-row { display: flex; justify-content: space-between; align-items: center; margin-top: 16px; padding-top: 8px; border-top: 1px solid rgba(232,221,209,.8); font-size: 12px; color: var(--muted); }
.rating { color: #d77b22; font-weight: 700; }
.how { display: grid; grid-template-columns: .8fr 1.2fr; gap: 46px; padding: 38px 36px; margin-top: 86px; background: linear-gradient(135deg,#254b42,#1d3c37 60%,#183631); color: #f8f3ec; border-radius: 28px; }
.how .eyebrow { background: rgba(255,255,255,.08); border-color: rgba(170,210,192,.18); color: #bbdfca; }
.how .section-title { font-size: 40px; margin-top: 8px; }
.how p { color: #d7e4dd; line-height: 1.6; max-width: 490px; }
.step-list { display: grid; gap: 12px; }
.step { display: flex; gap: 14px; align-items: center; padding: 16px; border-radius: 16px; background: rgba(255,255,255,.08); border: 1px solid rgba(170,210,192,.18); }
.step-number { width: 31px; height: 31px; border-radius: 50%; display: grid; place-items: center; border: 1px solid rgba(180,214,197,.5); color: #d3e9dc; font-weight: 700; }
.step strong { display: block; font-size: 14px; }
.step span { display: block; margin-top: 3px; font-size: 12px; color: #c7d9cf; }
.ui-panel { margin: 10px 0; padding: 16px 18px; background: rgba(255,255,255,.72); border: 1px solid rgba(232,221,209,.85); border-radius: 18px; box-shadow: 0 8px 18px rgba(67,44,27,.03); }
.ui-panel h3 { margin: 10px 0 8px; font-size: 26px; }
.ui-panel p, .dense-section p { color: var(--muted); line-height: 1.65; margin: 0 0 10px; }
.mini-meta { display: flex; gap: 10px; flex-wrap: wrap; }
.mini-meta span { display: inline-block; padding: 5px 9px; background: #fff3e7; color: var(--orange-dark); border-radius: 999px; font-size: 10px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
.dense-section { margin: 16px auto; padding: 18px 20px; border: 1px solid rgba(232,221,209,.8); background: rgba(255,255,255,.7); border-radius: 20px; }
.dense-section h3 { margin: 12px 0 8px; font-size: 30px; }
.dense-section ul { margin: 8px 0 0; padding-left: 22px; color: var(--muted); line-height: 1.7; }
.site-footer { max-width: var(--max-width); margin: 0 auto; padding: 24px 28px 30px; display: flex; justify-content: space-between; color: #8c827a; font-size: 12px; }
.toast-region { position: fixed; right: 20px; bottom: 20px; z-index: 20; display: grid; gap: 8px; }
.toast { background: #2f3431; color: white; padding: 12px 15px; border-radius: 11px; box-shadow: var(--shadow); font-size: 13px; }
@media (max-width: 850px) {
  .topnav { display: none; }
  .hero { grid-template-columns: 1fr; padding-top: 24px; }
  .hero-art { min-height: 320px; }
  .value-strip { grid-template-columns: 1fr; }
  .recipe-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .search-panel { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .how { grid-template-columns: 1fr; }
}
@media (max-width: 520px) {
  .topbar, #app, .site-footer { padding-left: 16px; padding-right: 16px; }
  .hero { padding-left: 16px; padding-right: 16px; }
  .hero-actions { display: grid; grid-template-columns: 1fr; }
  .recipe-grid { grid-template-columns: 1fr; }
  .search-panel { grid-template-columns: 1fr; }
  .section-head { display: block; }
  .button { width: 100%; }
  .site-footer { flex-direction: column; gap: 6px; }
}
