@keyframes driftPulse {
  0% { transform: translateY(0px) scale(1); }
  100% { transform: translateY(-10px) scale(1.01); }
}

@keyframes slowZoom {
  0% { transform: scale(1); }
  100% { transform: scale(1.08); }
}

@keyframes shimmer {
  0% { filter: brightness(1); }
  50% { filter: brightness(1.09); }
  100% { filter: brightness(1); }
}

@keyframes floatTag {
  0% { transform: translate3d(0, 0, 0); }
  50% { transform: translate3d(10px, -8px, 0); }
  100% { transform: translate3d(0, 0, 0); }
}

.story-panel {
  position: relative;
  margin: 28px 0;
  border-radius: 30px;
  background: rgba(255, 255, 255, 0.8);
  border: 1px solid rgba(232, 221, 209, 0.9);
  box-shadow: 0 16px 34px rgba(44, 34, 20, 0.05);
  overflow: hidden;
}

.story-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 20px 22px 0;
}

.story-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 12px;
  border-radius: 999px;
  background: rgba(81, 123, 108, 0.08);
  color: var(--sage);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.story-meta {
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

.story-layout {
  display: grid;
  grid-template-columns: 1.05fr .95fr;
  gap: 22px;
  padding: 18px 22px 22px;
}

.story-copy h3 {
  margin: 0 0 10px;
  font-family: "Playfair Display", serif;
  font-size: clamp(28px, 2.4vw, 44px);
  line-height: 1.08;
  letter-spacing: -0.06em;
}

.story-copy p {
  margin: 0 0 14px;
  color: var(--muted);
  font-size: 15px;
  line-height: 1.8;
}

.story-copy ul {
  margin: 0;
  padding-left: 20px;
  color: var(--muted);
  line-height: 1.8;
}

.story-visual {
  position: relative;
  min-height: 300px;
  border-radius: 24px;
  overflow: hidden;
  border: 1px solid rgba(232, 221, 209, 0.8);
}

.story-visual img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  animation: slowZoom 10s ease-in-out infinite alternate;
}

.story-floating-tag {
  position: absolute;
  right: 14px;
  bottom: 14px;
  padding: 8px 12px;
  background: rgba(255, 255, 255, 0.8);
